import json,math
def add_v18(d,P,new_page,para,table,picture,link,is_glasses):
 O=P/'engineering-v18-results'
 if not (O/'test_register.json').exists():return
 s=json.loads((O/'test_register.json').read_text());t=json.loads((O/'torque_and_mass.json').read_text())
 new_page(d,'V18 A different folding hinge')
 para(d,'Project status: V18 six size passive hinge candidates with V10 native archives.')
 para(d,'V18 is our latest six size local STEP candidate. It replaces the sliding locking pin with a passive friction hinge and a separate stop at the wearing angle. The old pin return problem is removed from this mechanism. A different set of questions now matters: actual hinge torque, stop strength, wear, creep and fastener retention. None has a physical pass yet.')
 picture(d,'V18_hero','Actual child large and adult small STEP surfaces. Colours show parts, not chosen materials. Native editable Fusion archives remain V10.',5.8)
 para(d,'The stop supports outward cup rotation at the wearing angle. Folding inward moves the fork away from that stop. Friction is intended to hold the chosen angle. This is not a positive lock against every load direction, and an inward force can still fold the cup. We must test unwanted folding and handling before calling it suitable for a wearer.')
 if is_glasses:para(d,'This change is for the standalone defender. The separate Sony WH CH720N pad is unchanged. Its carrier is still generic, and its mounting measurements are deferred. No Sony fit, seal, bass, ANC, outgoing leakage or glasses comfort pass is added by the hinge work.')
 new_page(d,'V18 Geometry and rejected trials')
 table(d,['Size','Pose samples','Retracted box mm','Folded box mm'],[[r['size'].replace('_',' '),str(r['motion_samples']),' x '.join(str(round(v,1)) for v in r['retracted_box_mm']),' x '.join(str(round(v,1)) for v in r['folded_box_mm'])] for r in s['sizes']],[1.2,.8,2.45,2.45])
 para(d,'All six candidates have 38 valid solids. Together they pass '+str(sum(r['motion_samples'] for r in s['sizes']))+' sampled rigid poses and 24 outward stop queries. Eighteen saved wearing, retracted and folded STEP files were independently reimported and checked for solid count, validity, volume and pose bounds. These checks do not establish continuous clearance under load, safe finger gaps or durability.')
 picture(d,'V18_folded_CAD','Actual saved surfaces moved by the checked transforms. Same scale within each row. Folding angles and slider positions differ by size.',5.8)
 para(d,'The first stop relief collided after 5 degrees of folding. We retained that failed trial and widened the relief. The first adult layout also touched the cup shell; raising its hinge by 3 mm cleared the tested contact. Its guide bottom moved from z 82 to 85 mm to provide clearance at the shortest setting. The final rigid motion checks use these corrected parts.')
 para(d,'Folding is available, but its packing benefit varies. The band and protruding sliders limit the envelope, and the smallest child version has only a small bounding box reduction. A box comparison is not a carrying test or an optimised travel design. The rigid surfaces also do not represent actual fabric texture.')
 new_page(d,'V18 Torque and the wearing stop')
 picture(d,'V18_sections','Sections of actual saved hinge and stop solids. The spring is at a reference catalogue height; the nut and bolt use thread envelopes.',5.8)
 para(d,'Each hinge has two friction washers, backup washers, a disc spring, a bolt and a nut. The two stop patches total 32 square mm. The proposed spring reference is SCHNORR 000600 B, with 8 mm outside diameter, 4.2 mm inside diameter and 0.3 mm thickness. The catalogue gives a calculated force of 118 N at about 0.188 mm shortening. This is a reference point, not a purchased component or a measured preload.')
 link(d,'SCHNORR manufacturer catalogue reference',t['manufacturer_reference']['source'])
 para(d,'A fixed nut position cannot guarantee the same hinge torque when friction changes. Our proposed assembly target is 80 Nmm with a chosen 20 percent window, or 64 to 96 Nmm. We would measure the hinge torque directly, adjust it and qualify a locking method. Tightening torque at the nut is not a substitute. No actual calibrated assembly has been made.')
 para(d,'At a 65 mm grip lever the upper target corresponds to about 1.48 N; at 50 mm it is 1.92 N. These are engineering comparisons, not comfort or dexterity thresholds for autistic people. We have no spring force curve from which to infer the correct nut position or installed height. The CAD spring height therefore remains a catalogue reference pose.')
 new_page(d,'V18 What the numerical checks mean')
 picture(d,'V18_torque','Maximum static gravity moment over orientation for each assumed density scenario. This is not a measured mass or hinge holding result.',5.9)
 para(d,'The 18 density scenarios use the saved moving cup, pad and yoke volumes and centres of mass. Their largest calculated gravity moment is '+str(round(max(r['maximum_gravity_moment_over_orientation_Nmm'] for r in t['mass_cases']),2))+' Nmm, below the proposed minimum of 64 Nmm. With assumed friction from 0.1 to 0.3, the target preload falls within the comparison spring capacity. At friction 0.05 the comparison fails. We have not measured the friction pair, torque drift, shock resistance or resistance to accidental folding.')
 rows=[]
 for r in s['stop_mechanics']:
  m=r['meshes'][-1];rows.append([r['size'].replace('_',' '),f"{m['weighted_load_direction_displacement_mm']:.4f}",f"{m['max_von_mises_centroid_MPa']:.2f}",'Pass' if r['chosen_mesh_gate_pass'] else 'Not passed'])
 table(d,['Ideal stop fixture','Displacement mm','Sampled stress MPa','Chosen mesh gate'],rows,[2.2,1.5,1.6,1.6])
 para(d,'The stop fixtures apply a total of 13 N over both patches, representing an illustrative 2 N side force at a 65 mm lever and a 10 mm stop radius. Each stem is cut and fully fixed at the guide bottom. The assumed elastic modulus is 2000 MPa and Poisson ratio is 0.35. These separate fixtures omit actual pivot load sharing, guide contact, bolt preload and fork contact. They do not qualify complete joint strength.')
 para(d,'The two tongue and fork shapes in each size family were checked for equal geometry after translation. That allows a listed component fixture to be shared within its family. A Boolean equality query did not establish child band identity, so we independently reran the band fixtures for every size instead of transferring an old result.')
 new_page(d,'V18 Headband checks and the next decision')
 rows=[]
 for r in s['band_mechanics']['cases']:
  m=r['meshes'][-1];rows.append([r['size'].replace('_',' '),f"{m['guide_weighted_x_displacement_mm']:.3f}",f"{m['max_von_mises_centroid_MPa']:.2f}",str(round(100*r['last_stress_change_fraction'],2))+'%'])
 table(d,['Band fixture','Guide movement mm','Sampled stress MPa','Last stress change'],rows,[2.0,1.6,1.7,1.6])
 para(d,'Every band is loaded by 2 N at one guide end with ideal symmetry and crown datums. It is a separate elastic fixture with assumed modulus 2000 MPa and Poisson ratio 0.35. The selected final comparisons meet the chosen 5 percent displacement and sampled stress gates. The saved arrays also pass work and energy, force balance, fixed displacement, finite value, residual and positive element checks. Numerical datums do not model a real scalp, and sampled stress is not a material strength allowable.')
 table(d,['Comparison','What V18 adds','What remains unknown'],[['V17 sliding pin','Avoids the loaded pin return mechanism','Friction torque and stop retention need samples'],['Ordinary folding headphones','Six saved adjustable sizes and a proposed calibrated hinge','No better durability, comfort or size claim'],['Existing sensory earmuffs','Passive cup and soft zone concept with no generated audio','No measured attenuation or sensory acceptance advantage'],['Specialist glasses pads','Standalone pad learning can be shared','Sony mount and actual pressure and acoustic comparisons still needed']],[1.7,2.5,2.7])
 para(d,'The digital prototype package is ready to guide the next experiments. The complete product is not finished or released for manufacturing. We still need actual foam compression and recovery, cover stretch and friction, selected structural materials, measured headband and hinge forces, assembled joint tests, drop and cycle tests, pressure and climate measurements, voluntary wearer feedback and repeated acoustic tests. Earlier finite material screens are not a test of every possible material.')
 para(d,'For the Sony route, measure the original mount before making a model specific pad. Compare the original, a uniform new pad and our softer zone pad under the same measured conditions. No zero leakage, pain relief, universal fit, market superiority or lowest price claim is supported. Supplier quotes and verified production processes are still needed. Both reports retain the earlier results and failures and will be updated together when measured evidence is added.')
